(function(){'use strict';const $=id=>document.getElementById(id),engine=new Staging.Sequence(),labels={ready:'발사 준비',countdown:'카운트다운',ignition:'점화 · 추력 상승',ascent:'상승 중',coast:'연소 종료 · 관성 상승',separated:'단분리 · 관성 상승',falling:'추진체 낙하 중',upper_fall:'추진체 지면 도달 · 상단 낙하',complete:'관찰 종료'};let view=null,paused=false,rate=1,last=null,history=[],sample=0,lastPaint=0;
try{view=new LaunchScene.View($('viewport'));}catch(e){$('render-error').hidden=false;$('render-error').textContent='3D 화면을 열 수 없습니다. Chrome/Edge의 그래픽 가속을 확인하세요. '+e.message;}
function record(){history.push({...engine.out});}record();
$('launch').addEventListener('click',()=>{engine.start();paused=false;paint();});$('pause').addEventListener('click',()=>{paused=!paused;paint();});$('reset').addEventListener('click',()=>{engine.reset();history=[];sample=0;paused=false;record();view?.reset();paint();});$('cutoff').addEventListener('click',()=>{engine.cutoff();paint();});$('rate').addEventListener('change',e=>{rate=Number(e.target.value);});
for(const [id,key] of [['cutaway','cutaway'],['trail','showTrail'],['exhaust','showExhaust']])$(id).addEventListener('change',e=>{if(view)view[key]=e.target.checked;});for(const [mode,label] of [['follow','추진체 추적 카메라'],['upper','상단 추적 카메라'],['overview','두 기체 전체 보기'],['pad','발사대 고정 카메라'],['top','상부 추적 카메라']])$('cam-'+mode).addEventListener('click',()=>{if(view)view.mode=mode;$('camera-label').textContent=label;for(const m of ['follow','upper','overview','pad','top'])$('cam-'+m).classList.toggle('active',m===mode);});
$('fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('viewport').requestFullscreen();}catch{$('notice').textContent='전체 화면이 제한된 환경입니다. 새 탭에서 열어 주세요.';}});$('about').addEventListener('click',()=>$('info').showModal());$('close-info').addEventListener('click',()=>$('info').close());$('chart-mode').addEventListener('change',draw);
$('csv').addEventListener('click',()=>{const keys=['time','height','velocity','acceleration','fuel','mass','thrust','weight','drag','state','separated','upperHeight','upperVelocity','boosterHeight','boosterVelocity','upperMass','boosterMass','upperGrounded','boosterGrounded'];const lines=['model,'+keys.join(','),...history.map(r=>'educational_split_bodies_v02,'+keys.map(k=>r[k]).join(','))];const url=URL.createObjectURL(new Blob(['\ufeff'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='launch-experiment.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('notice').textContent=history.length+'개 시점의 실험 기록을 저장했습니다.';});
function paint(){const o=engine.out;$('phase-detail').textContent=o.separated?'단분리 완료 · 추진체 '+o.boosterHeight.toFixed(1)+' m / 상단 '+o.upperHeight.toFixed(1)+' m':'점화 후 가정 시점에 자동 단분리';for(const id of ['height','velocity','acceleration'])$(id).textContent=o[id].toFixed(1);$('fuel').textContent=(o.fuel/2*100).toFixed(0);$('fuel-kg').textContent=o.fuel.toFixed(2)+' kg';$('fuel-bar').style.width=o.fuel/2*100+'%';for(const id of ['thrust','weight','drag'])$(id).textContent=o[id].toFixed(1)+' N';$('mass').textContent=o.mass.toFixed(2)+' kg';$('status').textContent=paused?'일시정지':labels[engine.state];$('clock').textContent='T '+(engine.t<3?'− ':'+ ')+Math.abs(engine.t-3).toFixed(1)+' s';$('launch').disabled=engine.state!=='ready';$('cutoff').disabled=['ready','complete','coast'].includes(engine.state)||engine.cut;$('pause').textContent=paused?'재생':'일시정지';$('event-log').innerHTML=engine.events.length?engine.events.map(e=>'<li><span>'+e.time.toFixed(1)+' s</span> · '+e.label+'</li>').join(''):'<li>명령 대기</li>';if(engine.state==='complete')$('notice').textContent='관찰 종료 · 추진체 최고 고도 '+o.peak.toFixed(1)+' m. 초기화하면 다시 실행할 수 있습니다.';draw();}
function draw(){const c=$('chart'),ctx=c.getContext('2d');if(!ctx)return;const w=c.getBoundingClientRect().width||600,h=180,dpr=Math.min(devicePixelRatio||1,2);if(c.width!==Math.round(w*dpr)||c.height!==h*dpr){c.width=Math.round(w*dpr);c.height=h*dpr;}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);const mode=$('chart-mode').value||'height',keys=mode==='forces'?['thrust','weight','drag']:mode==='height'?['boosterHeight','upperHeight']:[mode],colors=['#8ce6c7','#f4c393','#7ba8e3'],max=Math.max(mode==='forces'?110:10,...history.flatMap(p=>keys.map(k=>Math.abs(p[k])*1.1))),min=Math.min(0,...history.flatMap(p=>keys.map(k=>p[k]*1.1))),end=Math.max(10,engine.t),x=t=>38+t/end*(w-50),y=v=>145-(v-min)/(max-min)*130;ctx.font='10px system-ui';for(let i=0;i<=4;i++){const v=min+(max-min)*i/4;ctx.strokeStyle='#263c50';ctx.beginPath();ctx.moveTo(38,y(v));ctx.lineTo(w-12,y(v));ctx.stroke();ctx.fillStyle='#8aa1b5';ctx.fillText(v.toFixed(0),0,y(v)+3);ctx.fillText((end*i/4).toFixed(0)+'s',x(end*i/4)-5,170);}keys.forEach((k,i)=>{ctx.strokeStyle=colors[i];ctx.lineWidth=1.8;ctx.beginPath();history.forEach((p,j)=>j?ctx.lineTo(x(p.time),y(p[k])):ctx.moveTo(x(p.time),y(p[k])));ctx.stroke();});$('legend').textContent=mode==='forces'?'● 추력 (민트)　● 중력 (주황)　● 저항 (파랑) [N]':mode==='velocity'?'수직 속도 [m/s] · 시간 [s]':'● 추진체 (민트)　● 상단 (주황) 고도 [m] · 시간 [s]';}
function frame(now){let dt=last===null?0:Math.min(.1,(now-last)/1000)*rate;last=now;if(paused||document.hidden||engine.state==='ready'||engine.state==='complete')dt=0;while(dt>1e-9){const h=Math.min(.005,dt);engine.step(h);sample+=h;if(sample>=.1-1e-9||engine.state==='complete'){record();sample=0;}dt-=h;if(engine.state==='complete')break;}if(view){try{view.update(engine.out);}catch(e){$('render-error').hidden=false;$('render-error').textContent='3D 표시 오류: '+e.message;view=null;}}if(now-lastPaint>100){paint();lastPaint=now;}requestAnimationFrame(frame);}
paint();requestAnimationFrame(frame);globalThis.launchLab={engine,getHistory:()=>history.map(p=>({...p})),getView:()=>view};
})();
